"""X-only descriptive decisions and a maximum-three-contrast Phase IV design."""
import numpy as np
import pandas as pd
from .execution import ROOT,OUT,DYNAMICS

def table(d,cols=None):
    d=d[cols].copy() if cols else d.copy();d=d.fillna('no identificable')
    for c in d:d[c]=d[c].map(lambda x:f'{x:.3f}' if isinstance(x,(float,np.floating)) else str(x))
    return '| '+' | '.join(d.columns)+' |\n|'+'---|'*len(d.columns)+'\n'+'\n'.join('| '+' | '.join(row)+' |' for row in d.to_numpy())

def build(catalog,comp,stable,dominant):
    dynamics=pd.read_csv(OUT/'audit/dynamics_redundancy.csv');time=pd.read_csv(OUT/'audit/temporal_sensitivity.csv');coverage=pd.read_csv(OUT/'audit/temporal_coverage.csv')
    summary=time.groupby(['sensor','index','statistic','case']).absolute_change.agg(['median',lambda v:v.quantile(.9),'max']).reset_index().rename(columns={'<lambda_0>':'p90'})
    summary.to_csv(OUT/'audit/temporal_sensitivity_summary.csv',index=False)
    decisions=[]
    for row in catalog.itertuples():
        q=comp[(comp.scope=='138')&comp.block.eq(row.block)&comp.kind.eq(row.kind)&comp['mode'].eq(row.mode)]
        base=q[q.dimensions.eq(row.baseline_dimensions)].iloc[0]
        s=stable[stable.representation.eq(row.representation)];boot=s[s.case.str.startswith('profile_bootstrap')].overlap.dropna()
        omissions=s[s.case.isin(['omit_dominant','omit_Chignahuapan'])].overlap.dropna()
        median=float(boot.median()) if len(boot) else np.nan
        status='B — exploratoria';why='contraste disponible; compactación, estabilidad y significado requieren evaluación conjunta'
        if base.dimensions==0 or base.contrasting_profiles==0:
            status='C — no prioritaria para diferenciación intraperfil';why='sin contraste local en estos perfiles; puede representar estructura entre perfiles'
        elif row.block=='soil_groups_original' or 'hellinger' in row.block:
            status='B — exploratoria cartográfica';why='contraste map-based; escala250k y composición/soporte limitan interpretación parcelaria'
        elif row.block in ['dynamics_original','history_ndvi2']:
            status='A — técnicamente lista para prueba';why='dos indicadores originales definidos, sin compresión artificial; disponibilidad y soporte verificables; no implica utilidad predictiva'
        elif row.baseline_dimensions<=5 and base.outside_contrasting_profiles>=3 and base.outside_contrast_parcels>=20 and len(boot)>=8 and median>=.8 and len(omissions)==2 and omissions.min()>=.7:
            status='A — técnicamente lista para prueba';why='dimensión compacta y subespacio relativamente estable con contraste fuera de perfiles dominantes; revisar retención antes de elegir k'
        if row.mode=='within':
            status='B — diagnóstico intraperfil';why='centrado por perfil es descriptivo; perfiles nuevos requieren política de referencia; no proponer automáticamente como entrada'
        decisions.append(dict(representation=row.representation,category=status,reason=why,dimensions=row.baseline_dimensions,bootstrap_median_overlap=median,omission_min_overlap=float(omissions.min()) if len(omissions) else np.nan,within_reconstruction_fraction=base.within_reconstruction_fraction,within_reconstruction_equal_profile=base.within_reconstruction_equal_profile,outside_contrast_profiles=base.outside_contrasting_profiles,outside_contrast_parcels=base.outside_contrast_parcels))
    dec=pd.DataFrame(decisions);dec.to_csv(OUT/'audit/descriptive_classification.csv',index=False)
    catalog=catalog.merge(dec[['representation','category','reason']],on='representation',validate='one_to_one');catalog.to_csv(OUT/'representation_catalog.csv',index=False)
    compare=comp[comp.scope.eq('138')&comp.block.isin(['dynamics_original','history_ndvi2','satellite_joint','sentinel_current','planet_current','terrain_continuous','climate_monthly_between'])]
    lines=['# Fase III: representaciones complementarias condicionadas a C-T3','', 'Se estudió solo X. Rendimiento, errores OOF, VIP y asociaciones con Y no ajustaron ni compararon representaciones. La evidencia previa justificó los bloques. Se reutilizaron matrices197 y los IDs138 existentes; no se reconstruyeron las1867columnas. Se verificaron los manifests de fasesI/II y se conservaron los65folds originales para diseño posterior.','', '## Métodos y límites','', 'R0 conserva indicadores originales; R1 usa PCA/SVD por bloque; R2 reduce subgrupos sensor/índice/ventana/familia a min(2,k90) y equilibra la energía de cada subgrupo y sensor antes de la segunda PCA. No hay score agregado ni selección por rendimiento. Se comparan total, residualización lineal sobre las cuatro entradasC-T3 y centrado por perfil: no son equivalentes.','', 'Los análisis138 y197 se separan. Todo ajuste de197 es descriptivo/transductivo. Las59parcelas no reciben rendimiento predicho. Los scores descriptivos no son componentes inductivas congeladas. El transformador futuro conserva mediana, escala, proyecciónX y bases ajustadas en entrenamiento; para centrado por perfil no observado utiliza la referencia global de entrenamiento, con reserva de cambio de dominio.','', 'Rangos y spectra describen geometría de X, no información condicional independiente ni capacidad predictiva. Composición de suelo/geología: raíces de fracciones mutuamente excluyentes que suman1 (Hellinger), sin pseudocuentas; las coberturas que mencionan grupos se conservan comoR0y no reciben PCA. No hay codificación ordinal de categorías. DEM120m/vecindad y cartografía250k mantienen su soporte original.','', 'Retención es reconstrucción lineal de X desde scores:1−SSE/TSS. Se calcula total, intraperfil por observación y equilibrada por perfil. Puede ser negativa: una reconstrucción global puede fallar en un contraste local. Se informa también reconstrucción del residuo lineal de X respecto deC-T3 a partir de scores residualizados frente al mismo núcleo. No son métricas de rendimiento.','', '## 1. Información ya representada por C-T3','', 'Total, fracción temprana y concentración de lluvia, más estado espectral NDVI mayo. Dentro de un perfil de lluvia las tres primeras son constantes. Las representaciones residuales eliminan solo reconstrucción lineal, no toda dependencia respecto del núcleo.','', '## 2–4. Dimensiones restantes, contraste local y estructura entre perfiles','',table(compare,['block','kind','mode','dimensions','components_90','components_95','effective_rank','contrasting_profiles','outside_contrasting_profiles','within_reconstruction_fraction','within_reconstruction_equal_profile','CT3_residual_within_reconstruction_fraction']),'', 'Los modos climáticos centrados por perfil sin dimensiones no son candidatos locales. Las componentes de mapas pueden variar dentro del perfil pero su resolución no permite atribuir fertilidad o geología parcelaria fina. La fracción de energía intraperfil concentrada en los dos perfiles grandes está separada en block_comparison.csv; no contar parejas como observaciones nuevas.','', '## 5. Redundancia entre sensores y transformaciones','', 'Se agruparon764descriptores actualesSentinel y277Planet por índice, ventana y familia;82descriptoresSentinel de historia/anomalías quedan fuera del bloque actual. Las diferencias entre sensor, índice espectral y estadístico no equivalen a fuentes independientes. La sensibilidad deduplicate mide |r|>=0.99999 enXdel ajuste; igualdad numérica no certifica equivalencia física. La comparación de escalados puede cambiar dirección/peso sin cambiar el número de columnas.','', '## 6. LAI, SAVI y NDVI mayo','',table(dynamics[dynamics.scope.eq('138')]),'', 'LAI/SAVI se conservan como indicadores originales. Su correlación total y centrada por perfil indica solapamiento geométrico, no causalidad ni utilidad incremental. Las raíces/fechas no se interpretan como fenología validada. HayLAInegativos en fuente. La extracción de las dos primitivas originales se reprodujo desde fechas irregulares antes de perturbar observaciones.','', '## Sensibilidad temporal','',table(summary[summary.sensor.eq('S2')&summary.statistic.isin(['runup_start_day','runup_duration'])],['index','statistic','case','median','p90','max']),'', 'Se omitió cada mes y se eliminaron aleatoriamente20%de fechas en cuatro perturbaciones con semilla2026. Se mantuvieron fechas reales, medias de duplicados y valores válidos; no interpolación ni máscara inventada. Omitir todo un mes es una perturbación fuerte, no un error de medición esperado. q10yAUCnormalizada de NDVI representan controles de disponibilidadSentinel/Planet; no certifican todos los índices de cada sensor.','', '## 7. Retención de contrastes por PCA','', 'No elegir ksolo por90/95%de varianza global. Se conservan alternativas2/5/k90/k95 y ambas ponderaciones intraperfil. Una dirección de poca varianza global puede contener contraste local; las tablas permiten ver el costo de compacidad sin asumir que más contraste predice mejor.','', '## 8. Representación jerárquica','', 'La jerarquía tiene un objetivo de ponderación: impedir dominio de un sensor por cantidad de descriptores. La integración usa información lineal, puede perder contrastes en ambas etapas y no tiene garantizada ventaja. Comparar sus reconstrucciones con PCAglobal en el mismo bloque conjunto y mismo k. Sus bases efectivas se interpretan mediante los seis pesos mayores por dimensión, sin etiquetarlas automáticamente como factores agronómicos.','', '## 9. Clasificación técnica','',table(dec), '', 'A significa transformaciones definidas y soporte suficiente para una prueba, no prioridad predictiva ni superioridad. Historia2es técnicamente sencilla pero permanece secundaria por evidencia previa. B conserva problemas de estabilidad/compresión/soporte; Cse refiere a poca prioridad local, no irrelevancia agronómica. La clasificación usa criterios separados, no suma arbitraria. Los criterios descriptivos de estabilidad son convenciones para lectura, no inferencia probabilística.','', '## 10. Mediciones necesarias','', 'Validación de la escalaLAIyeventos fenológicos con fechas reales; método de medición de rendimientos y superficie cosechada; manejo/variedad/siembra; suelo parcelario y humedad/agua; nuevas campañas y varios perfiles repetidos. Más transformaciones del mismo mapa o serie no sustituyen estas mediciones.','', '## Reproducibilidad y límites','', 'Subespacios comparados mediante ángulos principales en una métrica común,12remuestreos de perfiles, omisiones dominantes/Chignahuapan, IQRconSDfallback y eliminación de redundancias. No son12muestras independientes. Estabilidad1cuando se compara todo el espacio de uno o dos indicadores es trivial y no certifica precisión temporal. La dimensiónkse limita al rango respaldado; cambios de rango se registran como falta de soporte, no fallos numéricos.','', 'Conclusión: existe contraste Xadicional que puede representarse mediante indicadores temporales originales y bases compactas por bloques. Su preservación depende del modo, pesos, k y soporte. Esta fase concluye estructura geométrica y viabilidad técnica; no demuestra ganancia predictiva ni independencia condicional. Se entrega FaseIVpara revisión y se detiene.','', 'Referencias: [PCA](https://scikit-learn.org/1.7/modules/generated/sklearn.decomposition.PCA.html), [ajustes solo dentro del entrenamiento](https://scikit-learn.org/1.7/common_pitfalls.html).']
    (OUT/'representation_report.md').write_text('\n'.join(lines),encoding='utf-8')
    iv='''# Diseño de Fase IV — pendiente de revisión, no ejecutado

Máximo tres contrastes, con C-T3 congelado como referencia común. No ejecutar una representación solo por categoría A. No usar scores descriptivos197 como entradas. La evidencia de F4-E2 motivó LAI: cambiar lluvia mensual por compacta no convierte esta hipótesis en validación independiente.

1. **IV-1: C-T3 + inicio del ascenso LAI.** Hipótesis: dimensión temporal local complementaria al estadoNDVI. Matriz compact4+un indicador original. Objetivo: rendimiento absoluto con ElasticNet del mismo grid12, transformación original y selección interna; diferencias intraperfil como evaluación externa, no nueva pérdidaB. Control: C-T3archivado. Refutación: ausencia de beneficio local o daño territorial. Costo estimado3185ajustes para65folds×(12×4+1), sin nuevo control si se recupera.
2. **IV-2: C-T3 + LAIinicio + SAVIduración.** Hipótesis propia: las dos dimensiones temporales no son completamente redundantes y su combinación puede aportar algo distinto deLAIsolo. Mismo estimador/grid y matriz compact4+dos indicadores. ControlesC-T3eIV-1. La distinta sensibilidad temporal obliga a mantener ambas ablaciones. Detener siSAVIno aporta incrementalmente o genera transferencia inestable; no expandir índices. Costo estimado3185ajustes. No es automático: revisar antes el soporte y la sensibilidad temporal de esta entrega.
3. **IV-3, reserva: C-T3 + representación satelital jerárquica residualizada de X.** Solo si la retención, estabilidad e interpretabilidad justifican una pregunta distinta deIV-2. Matrizcore4+scores de bloques actualesSentinel/Planet. ObjetivoYconEN; noPLSni residual deY. En cada entrenamiento imputar/escalarZ, ajustarproyecciónZsobrecoreX, realizarprimerasPCApor subgrupos y equilibrarsensores, luegoPCAfinal. Proponer k=[2,5]si soportado y gridEN12; todos seleccionados en validación interna. ControlC-T3, eIV-2como referencia interpretativa. Costo máximo6305ajustesENexternos/internos, además de transformacionesXcacheables. Puede cancelarse si no preserva contraste suficiente o duplica las hipótesis ya investigadasL/M.

No se incluyen historia, cartografía o corrección residual de árboles en esta primera propuesta. Si se plantea un corrector después, será otra autorización con targets cross-fitted anidados y amplitud incluyendo0; no reciclar erroresOOFglobales.

Conservar65particiones externas y sus internas originales. Todo tuning o componente se ajusta dentro de cada entrenamiento interno; refit del entrenamiento externo tras elegir configuración, evaluación externa una vez. Scores/centros/medianas197prohibidos en la validación inductiva. Los protocolos aleatorio,perfil,municipal y espacial siguen separados. No seleccionar ganador con folds externos y presentar esa misma selección como confirmación.

Métricas: RMSE/MAE/sesgo sobreOOFcompletas por repetición y media de10repeticiones aleatorias; errores por municipio/bloque y omisiones sin refits; errores bajos/altos solo posteriores; perfiles nuevos/conocidos; pares solo bajo mismo modelo externo, RMSE/MAE por parejas y con igual peso por perfil, dentro/fueraChignahuapan. Parejas y repeticiones no son independientes.

Criterios propuestos para revisión: beneficio local≥0.01t/ha en RMSEde diferencias sin daño>0.01en ambas ponderaciones; no deterioro>0.01en RMSE/MAEde ningún protocolo absoluto; comprobar sesgo/omisiones y ganancias repartidas. Estos márgenes son convenciones prácticas no validadas económicamente, no significación estadística. Una ganancia solo aleatoria no demuestra transferencia. Detener ante daño territorial, elección persistente del control o ganancias concentradas; no ampliar retrospectivamente grids, variables o k. Obtener nueva campaña/municipios para confirmación independiente antes de promoción.

Estado: DISEÑO, CERO ENTRENAMIENTOS. Champion, C-T3, F8 y59PREDpermanecen intactos.
'''
    (OUT/'phase_iv_design.md').write_text(iv,encoding='utf-8')
    from matplotlib import pyplot as plt
    a=comp[comp.scope.eq('138')&comp.block.eq('satellite_joint')&comp['mode'].eq('ct3_residual')]
    fig,ax=plt.subplots(figsize=(7,4))
    for kind,g in a.groupby('kind'):ax.plot(g.dimensions,g.within_reconstruction_equal_profile,marker='o',label=kind)
    ax.set(xlabel='Dimensiones retenidas',ylabel='Reconstrucción intraperfil equilibrada',title='Contraste satelital residual a C-T3');ax.legend();fig.tight_layout();fig.savefig(OUT/'figures/satellite_reconstruction.png',dpi=150);plt.close(fig)
    fig,ax=plt.subplots(figsize=(7,4));s=summary[summary.sensor.eq('S2')&summary.statistic.isin(['runup_start_day','runup_duration'])&summary.case.str.startswith('omit_month')]
    for (idx,stat),g in s.groupby(['index','statistic']):ax.plot(g.case.str[-1].astype(int),g.p90,marker='o',label=idx+' '+stat)
    ax.set(xlabel='Mes omitido',ylabel='P90 del cambio absoluto (días)',title='Sensibilidad de descriptores temporales');ax.legend();fig.tight_layout();fig.savefig(OUT/'figures/temporal_sensitivity.png',dpi=150);plt.close(fig)
    doc=ROOT/'documentation/ct3_information_phase_iii.md'
    if doc.exists():raise FileExistsError(doc)
    doc.write_text('# Fase III: representaciones condicionadas a C-T3\n\n[Informe técnico](../outputs/research/ct3_incremental_information/phase_iii/v1/representation_report.md).\n\n[Catálogo](../outputs/research/ct3_incremental_information/phase_iii/v1/representation_catalog.csv), [comparación](../outputs/research/ct3_incremental_information/phase_iii/v1/block_comparison.csv), [estabilidad](../outputs/research/ct3_incremental_information/phase_iii/v1/stability_analysis.csv).\n\n[Fase IV, propuesta sin ejecutar](../outputs/research/ct3_incremental_information/phase_iii/v1/phase_iv_design.md).\n\nImplementación src/ct3_information/phase_iii; ejecución scripts/374_ct3_information_phase_iii.py. CeroYen ajuste/selección de representaciones, cero nuevos modelos de rendimiento, cero59PRED.\n',encoding='utf-8')
